@Composable
fun AncTheme(content: @Composable () -> Unit) {
    val colorScheme = lightColorScheme(
        primary = Color(0xFF00695C),
        onPrimary = Color.White,
        primaryContainer = Color(0xFFB2DFDB),
        onPrimaryContainer = Color(0xFF00251A),
        secondary = Color(0xFFAD1457),
        onSecondary = Color.White,
        secondaryContainer = Color(0xFFF8BBD0),
        onSecondaryContainer = Color(0xFF560027),
        background = Color(0xFFF5F7F8),
        surface = Color.White,
        error = Color(0xFFC62828)
    )
    MaterialTheme(
        colorScheme = colorScheme,
        content = content
    )
}

@Composable
fun AncAppScreen(viewModel: AncViewModel = viewModel()) {
    val screen = viewModel.screenState

    BackHandler(enabled = screen !is ScreenState.Register) {
        viewModel.navigateBack()
    }

    when (screen) {
        is ScreenState.Register -> {
            RegisterScreen(
                patients = viewModel.patients,
                isLoading = viewModel.isLoading,
                errorMessage = viewModel.errorMessage,
                onRefresh = { viewModel.refreshAll() },
                onSelectPatient = { viewModel.openPatientDetail(it.id) }
            )
        }
        is ScreenState.PatientDetail -> {
            val patient = viewModel.patients.find { it.id == screen.patientId }
            val visits = viewModel.visitsByPatient[screen.patientId].orEmpty()
            if (patient != null) {
                PatientDetailScreen(
                    patient = patient,
                    visits = visits,
                    isLoading = viewModel.isLoading,
                    errorMessage = viewModel.errorMessage,
                    onBack = { viewModel.navigateBack() },
                    onRefresh = { viewModel.refreshAll() },
                    onRecordNewVisit = { viewModel.openNewVisitForm(patient.id) }
                )
            } else {
                RegisterScreen(
                    patients = viewModel.patients,
                    isLoading = viewModel.isLoading,
                    errorMessage = viewModel.errorMessage,
                    onRefresh = { viewModel.refreshAll() },
                    onSelectPatient = { viewModel.openPatientDetail(it.id) }
                )
            }
        }
        is ScreenState.NewVisitForm -> {
            val patient = viewModel.patients.find { it.id == screen.patientId }
            if (patient != null) {
                NewVisitFormScreen(
                    patient = patient,
                    questionnaire = viewModel.questionnaire ?: defaultAncQuestionnaire(),
                    isSaving = viewModel.isSaving,
                    errorMessage = viewModel.errorMessage,
                    onBack = { viewModel.navigateBack() },
                    onSave = { input ->
                        viewModel.saveVisit(
                            patientId = patient.id,
                            input = input,
                            onSuccess = {}
                        )
                    }
                )
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RegisterScreen(
    patients: List<PatientSummary>,
    isLoading: Boolean,
    errorMessage: String?,
    onRefresh: () -> Unit,
    onSelectPatient: (PatientSummary) -> Unit
) {
    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            text = "ANC Register",
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.Bold
                        )
                        Text(
                            text = "Pregnant patients sorted by due date (soonest first)",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.85f)
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primary,
                    titleContentColor = MaterialTheme.colorScheme.onPrimary,
                    actionIconContentColor = MaterialTheme.colorScheme.onPrimary
                ),
                actions = {
                    IconButton(onClick = onRefresh) {
                        Icon(
                            imageVector = Icons.Default.Refresh,
                            contentDescription = "Refresh"
                        )
                    }
                }
            )
        }
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
        ) {
            if (errorMessage != null) {
                ErrorBanner(message = errorMessage, onRetry = onRefresh)
            }

            if (isLoading && patients.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Column(horizontalAlignment = Alignment.CenterHorizontally) {
                        CircularProgressIndicator()
                        Spacer(modifier = Modifier.height(12.dp))
                        Text("Loading ANC register from FHIR server...")
                    }
                }
            } else if (patients.isEmpty()) {
                Box(
                    modifier = Modifier.fillMaxSize(),
                    contentAlignment = Alignment.Center
                ) {
                    Text("No pregnant patients found on server.")
                }
            } else {
                LazyColumn(
                    modifier = Modifier.fillMaxSize(),
                    contentPadding = PaddingValues(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    items(patients, key = { it.id }) { patient ->
                        PatientRegisterCard(
                            patient = patient,
                            onClick = { onSelectPatient(patient) }
                        )
                    }
                }
            }
        }
    }
}

